from collections.abc import Collection

def check_subset(sub, main):
    """
    Check if all elements of collection 'sub' are contained in collection 'main'.
    Works for any collections supporting iteration.
    """
    if not isinstance(sub, Collection) or not isinstance(main, Collection):
        raise TypeError("Both arguments must be collections.")

    main_counts = {}
    for item in main:
        main_counts[item] = main_counts.get(item, 0) + 1

    for item in sub:
        if main_counts.get(item, 0) == 0:
            return False
        main_counts[item] -= 1
    return True
```

