import re

def anti_shuffle(s):
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            result.append(part)
        else:
            # separate trailing non-letter characters
            match = re.match(r'([A-Za-z]+)([^A-Za-z]*)$', part)
            if match:
                word, trailing = match.groups()
                if len(word) > 1:
                    sorted_word = ''.join(sorted(word))
                else:
                    sorted_word = word
                result.append(sorted_word + trailing)
            else:
                # no letters in part, just add as is
                result.append(part)
    return ''.join(result)
```

